begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('entry_a')::uuid),(md5('entry_b')::uuid);
insert into profiles(id,display_name) values(md5('entry_a')::uuid,'A'),(md5('entry_b')::uuid,'B');
insert into account_preferences(owner_id) values(md5('entry_a')::uuid),(md5('entry_b')::uuid);
insert into exercises(owner_id,slug,name,exercise_type) values(md5('entry_b')::uuid,'entry_private','Private press','compound');
insert into exercises(id,owner_id,slug,name,exercise_type) values(md5('entry_custom')::uuid,md5('entry_a')::uuid,'entry_custom','My press','compound');
insert into exercise_movement_patterns(exercise_id,movement_pattern_id,is_primary) values(md5('entry_custom')::uuid,(select id from movement_patterns where slug='horizontal_push'),true);
insert into exercise_muscles(exercise_id,muscle_group_id,muscle_role) values(md5('entry_custom')::uuid,(select id from muscle_groups where slug='pectorals'),'primary');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('entry_b')::uuid,'role','authenticated')::text,true);
select set_config('body_test.foreign',(select id::text from exercises where slug='entry_private'),true);
select set_config('request.jwt.claims',json_build_object('sub',md5('entry_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.one',(select id::text from exercises where slug='barbell_bench_press'),true);
select set_config('body_test.two',(select id::text from exercises where slug='dumbbell_bench_press'),true);
select set_config('body_test.ids',array[current_setting('body_test.one')::uuid,current_setting('body_test.two')::uuid]::text,true);
select is(exercise_setup_slot(current_setting('body_test.one')::uuid)->>'intent','flat_press','canonical specific intent derived from active catalog');
select is((select count(*)::int from workout_setup_recents()),0,'no fabricated recents');
select throws_ok($$select start_exercise_workout(array[current_setting('body_test.foreign')::uuid],md5('entry_foreign')::uuid)$$,'22023',null,'foreign catalog ID rejected');
select throws_ok($$select start_exercise_workout(array[md5('missing')::uuid],md5('entry_missing')::uuid)$$,'22023',null,'unknown catalog ID rejected');
select throws_ok($$select start_exercise_workout(array[]::uuid[],md5('entry_empty')::uuid)$$,'22023',null,'empty list rejected');
select throws_ok($$select start_exercise_workout(array[current_setting('body_test.one')::uuid,current_setting('body_test.one')::uuid],md5('entry_dup')::uuid)$$,'22023',null,'same exercise duplicated is rejected');
select throws_ok($$select start_exercise_workout(array[current_setting('body_test.one')::uuid,null],md5('entry_null')::uuid)$$,'22023',null,'null ID rejected');
select is((select count(*)::int from workout_sessions),0,'invalid starts leave no partial sessions');
select set_config('body_test.w',start_exercise_workout(current_setting('body_test.ids')::uuid[],md5('entry_nonce')::uuid)::text,true);
select is(start_exercise_workout(current_setting('body_test.ids')::uuid[],md5('entry_nonce')::uuid),current_setting('body_test.w')::uuid,'retry returns same session');
select throws_ok($$select start_exercise_workout(array[current_setting('body_test.two')::uuid,current_setting('body_test.one')::uuid],md5('entry_nonce')::uuid)$$,'23514',null,'retry cannot reorder or replace payload');
select throws_ok($$select start_exercise_workout(array[current_setting('body_test.one')::uuid],md5('entry_concurrent')::uuid)$$,'23514',null,'second active session denied');
select is((select count(*)::int from workout_sessions),1,'one active session only');
select ok((select source_program_version_id is null and program_assignment_id is null and favorite_workout_id is null from workout_sessions where id=current_setting('body_test.w')::uuid),'independent source identity');
select is((select array_agg(exercise_id order by position) from workout_exercises where workout_session_id=current_setting('body_test.w')::uuid),current_setting('body_test.ids')::uuid[],'chosen canonical identities already bound in order');
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.w')::uuid and suggested_intent='flat_press'),2,'deliberate different exercises can share intent');
select ok((select bool_and(status='pending' and actual_reps is null and actual_weight_kg is null and completed_at is null and effort_scale is null and effort_value is null and not performed_to_failure and not inputs_confirmed) from workout_sets),'initial actuals remain empty and unrated');
select is((select count(*)::int from workout_sets),6,'normal working-set initializer reused');
select set_config('body_test.slots',(select ad_hoc_focus::text from workout_sessions where id=current_setting('body_test.w')::uuid),true);
select end_workout(current_setting('body_test.w')::uuid,'abandoned');
select throws_ok($$select start_suggested_workout((select jsonb_agg(x-'exerciseId') from jsonb_array_elements(current_setting('body_test.slots')::jsonb)x),md5('entry_ordinary')::uuid)$$,'22023',null,'ordinary movement-first duplicate intent remains rejected');
select throws_ok($$select start_suggested_workout(jsonb_set(current_setting('body_test.slots')::jsonb,'{0,title}','"Forged"'),md5('entry_forged')::uuid)$$,'22023',null,'explicit metadata cannot be supplied as authority');
select ok(exercise_setup_slot(md5('entry_custom')::uuid)->>'intent' is null,'private exercise uses valid taxonomy without fabricated curated intent');
select set_config('body_test.custom',start_exercise_workout(array[md5('entry_custom')::uuid],md5('entry_custom_start')::uuid)::text,true);
select is((select exercise_id from workout_exercises where workout_session_id=current_setting('body_test.custom')::uuid),md5('entry_custom')::uuid,'explicit private canonical choice retained without intent');
select end_workout(current_setting('body_test.custom')::uuid,'abandoned');
select throws_ok($$select start_exercise_workout((select array_agg(id) from (select id from exercises where archived_at is null limit 7)x),md5('entry_too_many')::uuid)$$,'22023',null,'setup caps six slots');
select set_config('body_test.w2',start_exercise_workout(array[current_setting('body_test.one')::uuid],md5('entry_recorded')::uuid)::text,true);
select set_config('body_test.item',(select id::text from workout_exercises where workout_session_id=current_setting('body_test.w2')::uuid),true);
select log_workout_set(p_item=>current_setting('body_test.item')::uuid,p_id=>(select id from workout_sets where workout_exercise_id=current_setting('body_test.item')::uuid order by position limit 1),p_operation=>'save',p_revision=>0,p_mutation=>md5('entry_log')::uuid,p_reps=>8,p_weight=>50,p_type=>'working',p_completed=>true);
select end_workout(current_setting('body_test.w2')::uuid,'completed');
select is((select array_agg(exercise_id) from workout_setup_recents()),array[current_setting('body_test.one')::uuid],'recents use actual qualifying completed history and deduplicate');
select set_config('request.jwt.claims',json_build_object('sub',md5('entry_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from workout_setup_recents()),0,'another owner cannot see recents');
select is((select count(*)::int from workout_sessions where id=current_setting('body_test.w')::uuid),0,'another owner cannot read setup sessions');
reset role;
update exercises set archived_at=clock_timestamp() where id=current_setting('body_test.one')::uuid;
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('entry_a')::uuid,'role','authenticated')::text,true);
select throws_ok($$select start_exercise_workout(array[current_setting('body_test.one')::uuid],md5('entry_archived')::uuid)$$,'22023',null,'archived exercises rejected');
select is((select count(*)::int from workout_setup_recents()),0,'archived exercises absent from recents');
select is(start_exercise_workout(current_setting('body_test.ids')::uuid[],md5('entry_nonce')::uuid),current_setting('body_test.w')::uuid,'retry survives archived source without mutating history');
reset role;
set local role anon;
select throws_ok($$select start_exercise_workout(array[]::uuid[],gen_random_uuid())$$,'42501',null,'anonymous start denied');
select throws_ok($$select * from workout_setup_recents()$$,'42501',null,'anonymous recents denied');
reset role;
set local role service_role;
select throws_ok($$select start_exercise_workout(array[]::uuid[],gen_random_uuid())$$,'42501',null,'service role not exposed');
reset role;
select * from finish();rollback;
